import os
import time
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import ClientError


def _to_millis(dt: datetime) -> int:
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return int(dt.timestamp() * 1000)


def retrieve_recent_log_results(
    log_group_name: str,
    field_filters: Optional[Dict[str, str]] = None,
    minutes_back: int = 60,
    limit: int = 100,
    region_name: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """
    Retrieve recent Amazon CloudWatch Logs events filtered by field values and time range.

    Uses CloudWatch Logs filter_log_events with a filter pattern built from field filters.
    The time range is the last `minutes_back` minutes.

    Environment variables used:
      - AWS_REGION (optional if region_name is provided)
      - AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY (handled by boto3)
    """
    field_filters = field_filters or {}
    region_name = region_name or os.getenv("AWS_REGION", "us-east-1")

    logs_client = boto3.client("logs", region_name=region_name)

    end_time = datetime.now(timezone.utc)
    start_time = end_time - timedelta(minutes=minutes_back)

    # Build a CloudWatch Logs filter pattern for exact field matching when possible.
    # Example: { $.service = "api" && $.level = "error" }
    filter_pattern = ""
    if field_filters:
        clauses = [f'$.{key} = "{value}"' for key, value in field_filters.items()]
        filter_pattern = "{ " + " && ".join(clauses) + " }"

    results: List[Dict[str, Any]] = []
    next_token: Optional[str] = None

    while True:
        kwargs: Dict[str, Any] = {
            "logGroupName": log_group_name,
            "startTime": _to_millis(start_time),
            "endTime": _to_millis(end_time),
            "limit": max(1, min(limit, 10000)),
        }
        if filter_pattern:
            kwargs["filterPattern"] = filter_pattern
        if next_token:
            kwargs["nextToken"] = next_token

        try:
            response = logs_client.filter_log_events(**kwargs)
        except ClientError:
            raise

        for event in response.get("events", []):
            parsed_message: Any = event.get("message")
            if isinstance(parsed_message, str):
                stripped = parsed_message.strip()
                if stripped.startswith("{") and stripped.endswith("}"):
                    try:
                        import json

                        parsed_message = json.loads(stripped)
                    except Exception:
                        pass

            results.append(
                {
                    "log_group_name": event.get("logGroupName"),
                    "log_stream_name": event.get("logStreamName"),
                    "timestamp": event.get("timestamp"),
                    "ingestion_time": event.get("ingestionTime"),
                    "event_id": event.get("eventId"),
                    "message": parsed_message,
                }
            )

            if len(results) >= limit:
                return results[:limit]

        new_token = response.get("nextToken")
        if not new_token or new_token == next_token:
            break
        next_token = new_token

    return results[:limit]
